import{_ as a,a as t,o as r,a6 as d}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Orders","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/sales/orders/index.md","filePath":"api/graphql-api/admin/sales/orders/index.md","lastUpdated":1786429091000}'),n={name:"api/graphql-api/admin/sales/orders/index.md"};function i(o,e,s,c,l,h){return r(),t("div",null,e[0]||(e[0]=[d('<h1 id="orders" tabindex="-1">Orders <a class="header-anchor" href="#orders" aria-label="Permalink to &quot;Orders&quot;">​</a></h1><p>The Orders menu is the heart of Sales: browse every order in the store and run every per-order action. From here you can view a single order in full, drive the admin <strong>Create Order</strong> flow (reorder an existing order, or place a prepared draft cart), run order lifecycle actions (cancel an order, add and list its comments), and generate the documents an order produces — invoices, shipments, and refunds. It mirrors the admin <strong>Sales → Orders</strong> screen.</p><p>Invoices, shipments, and refunds are <strong>generated from an order</strong> here, but each also has its own store-wide menu listing every such document across all orders: see the <a href="/api/graphql-api/admin/sales/invoices/">Invoices</a>, <a href="/api/graphql-api/admin/sales/shipments/">Shipments</a>, and <a href="/api/graphql-api/admin/sales/refunds/">Refunds</a> overviews.</p><h2 id="creating-an-order-for-a-customer-admin-create-order" tabindex="-1">Creating an order for a customer (admin Create Order) <a class="header-anchor" href="#creating-an-order-for-a-customer-admin-create-order" aria-label="Permalink to &quot;Creating an order for a customer (admin Create Order)&quot;">​</a></h2><p>An admin can place an order <strong>on behalf of a customer</strong> — the same &quot;Create Order&quot; flow as the admin panel. It works through a <strong>draft cart</strong>: create a draft cart for the customer, add products, save the billing/shipping addresses, choose a shipping method and a payment method, then place the order. The draft cart is an internal building block of order creation, not a separate menu.</p><table tabindex="0"><thead><tr><th>Step</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/customers/create-draft-cart.html">Start a draft cart for a customer</a></td><td><code>createAdminDraftCart</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/sales/carts/get-cart.html">Get the draft cart</a></td><td><code>adminCart(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/sales/carts/add-item.html">Add an item</a> · <a href="/api/graphql-api/admin/sales/carts/update-items.html">update</a> · <a href="/api/graphql-api/admin/sales/carts/remove-item.html">remove</a></td><td><code>addItemAdminCart</code> / <code>updateItemsAdminCart</code> / <code>removeItemAdminCart</code> mutations</td></tr><tr><td><a href="/api/graphql-api/admin/sales/carts/save-address.html">Save addresses</a></td><td><code>saveAddressAdminCart</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/sales/carts/list-shipping-methods.html">List</a> / <a href="/api/graphql-api/admin/sales/carts/set-shipping-method.html">set</a> shipping method</td><td><code>adminCartShippingRates</code> query / <code>setShippingMethodAdminCart</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/sales/carts/list-payment-methods.html">List</a> / <a href="/api/graphql-api/admin/sales/carts/set-payment-method.html">set</a> payment method</td><td><code>adminCartPaymentMethods</code> query / <code>setPaymentMethodAdminCart</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/sales/carts/place-order.html">Place the order</a></td><td><code>createAdminPlaceOrder</code> mutation</td></tr></tbody></table><p>(There&#39;s also <a href="/api/graphql-api/admin/sales/carts/apply-coupon.html">apply</a> / <a href="/api/graphql-api/admin/sales/carts/remove-coupon.html">remove coupon</a> on the draft cart.) <a href="/api/graphql-api/admin/sales/orders/reorder.html">Reorder</a> is a shortcut that seeds a fresh draft cart from an existing order&#39;s items.</p><div class="tip custom-block"><p class="custom-block-title">Only saleable products can be added</p><p><a href="/api/graphql-api/admin/sales/carts/add-item.html">Add Item</a> accepts only products that are in stock and enabled. Adding an out-of-stock or disabled product returns a clear error and <strong>leaves the draft cart intact</strong> so you can add a different product — the cart is never lost. Booking products can&#39;t be added to an admin order (no admin Create-Order surface for them).</p></div><h2 id="the-order-lifecycle-—-which-action-in-what-order" tabindex="-1">The order lifecycle — which action, in what order <a class="header-anchor" href="#the-order-lifecycle-—-which-action-in-what-order" aria-label="Permalink to &quot;The order lifecycle — which action, in what order&quot;">​</a></h2><p>Once an order exists (placed through Create Order above, <a href="/api/graphql-api/admin/sales/orders/reorder.html">Reorder</a>, or the storefront), it moves through a lifecycle. Each action has prerequisites — this is the order they run in and what gates each one.</p><p><strong>1. Invoice — record payment.</strong> <a href="/api/graphql-api/admin/sales/orders/create-invoice.html">Create Invoice</a> records that payment was collected for some or all of the order&#39;s items. An order generally can&#39;t be refunded until it has been invoiced (you refund money that was billed). You can invoice part of an order now and the rest later. Not available for orders paid via <code>paypal_standard</code> (those are captured by the gateway, not the admin). Tick <strong>Create Transaction</strong> (<code>canCreateTransaction: true</code>) on the invoice to also record the payment as a transaction in the same step; to record a <strong>partial or later</strong> payment against an existing invoice, use <a href="/api/graphql-api/admin/sales/transactions/create.html">Create Transaction</a>.</p><p><strong>2. Ship — fulfil.</strong> <a href="/api/graphql-api/admin/sales/orders/create-shipment.html">Create Shipment</a> marks items as dispatched and records the carrier and tracking number. It needs items still awaiting shipment and enough stock at the chosen inventory source. Partial shipments are allowed.</p><p><strong>3. Refund — return money.</strong> <a href="/api/graphql-api/admin/sales/orders/create-refund.html">Create Refund</a> returns money for invoiced items and/or an arbitrary adjustment. Call <a href="/api/graphql-api/admin/sales/orders/refund-preview.html">Refund Preview</a> first to see the computed totals without writing anything. Requires something left to refund (an un-refunded invoiced amount or a returnable quantity).</p><p><strong>Cancel — abandon early.</strong> <a href="/api/graphql-api/admin/sales/orders/cancel.html">Cancel Order</a> is only possible while there is still something to cancel (nothing has been fully invoiced or shipped). A closed or fraud-flagged order can&#39;t be cancelled.</p><p><strong>Comments — any time.</strong> <a href="/api/graphql-api/admin/sales/orders/add-comment.html">Add Comment</a> / <a href="/api/graphql-api/admin/sales/orders/list-comments.html">List Comments</a> work at any stage; set <code>customerNotified</code> to email the customer the note.</p><p>Every action refuses with a clear error when its prerequisite isn&#39;t met — nothing left to invoice/ship/refund, the order is already closed or flagged, insufficient stock, or a payment method that can&#39;t be invoiced. A typical fulfilled order runs <strong>Create → Invoice → Ship</strong> (then an optional <strong>Refund</strong>); an abandoned one runs <strong>Create → Cancel</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Recording payments as transactions</p><p>A payment can be recorded as a transaction (which then shows in the <a href="/api/graphql-api/admin/sales/transactions/list.html">Transactions listing</a>) in two ways:</p><ul><li><strong>At invoice time</strong> — tick <strong>Create Transaction</strong> on <a href="/api/graphql-api/admin/sales/orders/create-invoice.html">Create Invoice</a> by sending <code>canCreateTransaction: true</code>. Records the <strong>full</strong> invoice amount in one step.</li><li><strong>Any time</strong> — <a href="/api/graphql-api/admin/sales/transactions/create.html">Create Transaction</a> (<code>createAdminTransaction</code>) records an <strong>arbitrary or partial</strong> payment against an existing invoice.</li></ul></div><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/sales/orders/list-orders.html">List Orders</a></td><td><code>adminOrders</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/sales/orders/order-detail.html">Order Detail</a></td><td><code>adminOrderDetail</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/sales/orders/reorder.html">Reorder</a></td><td><code>createAdminReorder</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/sales/carts/place-order.html">Place Order</a></td><td><code>createAdminPlaceOrder</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/sales/orders/cancel.html">Cancel Order</a></td><td><code>createAdminCancelOrder</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/sales/orders/add-comment.html">Add Comment</a></td><td><code>createAdminOrderComment</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/sales/orders/list-comments.html">List Comments</a></td><td><code>adminOrderComments</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/sales/orders/create-invoice.html">Create Invoice</a></td><td><code>createAdminInvoice</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/sales/orders/create-shipment.html">Create Shipment</a></td><td><code>createAdminShipment</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/sales/orders/create-refund.html">Create Refund</a></td><td><code>createAdminRefund</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/sales/orders/refund-preview.html">Refund Preview</a></td><td><code>previewAdminRefund</code> mutation</td></tr></tbody></table><p>All Orders endpoints require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',20)]))}const u=a(n,[["render",i]]);export{m as __pageData,u as default};
